import json,os,subprocess,sys,tempfile,unittest
from pathlib import Path
class Installer(unittest.TestCase):
 def test_upgrade_preserves_preferences_state_documents_and_disabled_autostart(self):
  source=Path(__file__).resolve().parents[1]
  with tempfile.TemporaryDirectory(prefix='installer-test-',dir=Path(tempfile.gettempdir())) as temp:
   home=Path(temp);install=home/'.local/share/nube-local';state=install/'state';app=install/'app';state.mkdir(parents=True);app.mkdir();(app/'old-version').write_text('0.4.0');(install/'installation.json').write_text('{"version":"0.4.0"}')
   prefs={'autostart':False,'uploadKiB':123,'notifications':False};(state/'preferences.json').write_text(json.dumps(prefs));(state/'sync-state.sqlite').write_bytes(b'durable-state');(state/'clientUid.json').write_text('private-client-id');docs=home/'ProtonDrive';docs.mkdir();(docs/'important.txt').write_text('keep this')
   result=subprocess.run([sys.executable,str(source/'scripts/install.py'),'--no-launch'],env={**os.environ,'HOME':str(home),'DBUS_SESSION_BUS_ADDRESS':'unix:path=/nonexistent/proton-test-bus','NUBE_LOCAL_PORT':'47839'},capture_output=True,text=True,timeout=30)
   self.assertEqual(result.returncode,0,result.stderr);self.assertEqual(json.loads((state/'preferences.json').read_text()),prefs);self.assertEqual((state/'sync-state.sqlite').read_bytes(),b'durable-state');self.assertEqual((state/'clientUid.json').read_text(),'private-client-id');self.assertEqual((docs/'important.txt').read_text(),'keep this');self.assertTrue((app/'src/system-settings.py').is_file());self.assertTrue((app/'src/bootstrap.py').is_file());self.assertTrue((install/'bootstrap.py').is_file());self.assertIn('bootstrap.py',(install/'nube-local').read_text());self.assertTrue((home/'.local/share/applications/app.nube_local.desktop.desktop').is_file());self.assertIn('NoDisplay=true',(home/'.local/share/applications/nube-local.desktop').read_text());self.assertEqual(json.loads((app/'release.json').read_text())['version'],'0.16.2');self.assertIn('X-GNOME-Autostart-enabled=false',(home/'.config/autostart/nube-local.desktop').read_text());self.assertTrue(any((p/'old-version').is_file() for p in install.glob('app-previous-*')))
if __name__=='__main__':unittest.main()
